// 项目实战“复刻面试自习室”第 6 关：题库数据库，建表和导入题目。
// 学习卡片由 .sites-runtime/cards/pj-db-*.mjs 生成（node .sites-runtime/lessons.mjs apply …），题目直接写在这里。
import type {AiLevel} from '../journey';

export const pjDb:AiLevel={id:'pj-db',title:'题库数据库：建表和导入题目',summary:'用 SQLite 保存题目：建表、在事务里导入 24 道种子题目，数据访问层改用参数化 SQL 查询',lessons:[
  {title:'这一关做什么：把题目存进数据库',body:'到现在为止，题目都写在代码里。这有两个大问题：一是想加一道题就得改代码、重启服务；二是以后用户的学习记录、答题记录这些“运行中产生的数据”，程序一重启就全丢了。\n这一关接入真正的数据库：\n一、题库扩充到 24 道题，放在 data/questions.json 里，这是题库的“原始数据”；\n二、程序启动时，如果数据库里还没有题目表，就建表；如果表是空的，就把 JSON 里的题目导入进去；\n三、数据访问层改成用 SQL 语句查数据库，接口的路径和返回格式完全不变。\n我们用 SQLite：整个数据库就是一个文件（data/zixishi.db），不用单独安装数据库服务，非常适合学习和小项目。后面会讲到，换成 MySQL 时主要改的是连接方式，SQL 基本一样。'},
  {title:'数据库、表、行和列',body:'可以把数据库想象成一个 Excel 文件：\n表（table）就是其中一张工作表，比如“题目表” questions、以后的“用户表” users；\n列（column）就是表头，规定每条数据有哪些字段、每个字段是什么类型，比如 id 是整数、title 是文本；\n行（row）就是一条条数据，一道题就是一行。\n和 Excel 不同的是，数据库对格式要求很严：建表时就要写清楚每一列的名字和类型，存进去的数据必须符合要求；还能加“约束”，比如 NOT NULL 表示这一列不能为空。\n每张表一般都有一个“主键”（PRIMARY KEY）：一列值不能重复、能唯一确定一行的数据，题目表的主键就是 id。按主键查一行数据非常快，因为数据库会自动给主键建索引（索引就像书的目录）。'},
  {title:'SQL：和数据库说话的语言',body:'SQL 是操作数据库的标准语言，各种数据库（SQLite、MySQL、PostgreSQL）大同小异。这一关用到四种语句：\n一、建表：CREATE TABLE IF NOT EXISTS questions (id INTEGER PRIMARY KEY, title TEXT NOT NULL, …)。IF NOT EXISTS 表示表已经存在就什么也不做，所以每次启动都可以放心执行；\n二、插入：INSERT INTO questions (id, title, …) VALUES (?, ?, …)，括号里先列出列名，再按顺序给出值；\n三、查询：SELECT id, title FROM questions WHERE category = ? ORDER BY id。SELECT 后面写要哪些列，FROM 写哪张表，WHERE 写筛选条件，ORDER BY 写按什么排序；\n四、计数：SELECT COUNT(*) FROM questions，返回表里一共有多少行。\nSQL 的关键字大小写都可以，习惯上关键字大写、表名和列名小写，读起来更清楚。'},
  {title:'一定要用参数化查询，防 SQL 注入',body:'上面 SQL 里的问号 ? 叫“占位符”。查询时，SQL 语句和参数值分开交给数据库，数据库只会把参数当作“一个值”，绝不会把它当成 SQL 的一部分来执行。这叫参数化查询。\n千万不要用字符串拼接来拼 SQL。比如写成 "SELECT * FROM questions WHERE category = \'" + category + "\'"，如果有人请求 /api/questions?category=\' OR \'1\'=\'1，拼出来的 SQL 就变成 WHERE category = \'\' OR \'1\'=\'1\'，条件永远成立，本来不该看到的数据全都出来了。要是拼进去的是删除语句，后果更严重。这种攻击叫 SQL 注入，是最常见、危害最大的漏洞之一。\n这一关的验收脚本会专门用这种请求试探你的接口。规则很简单：用户传来的任何值，都通过占位符传给数据库。'},
  {title:'事务：要么全做，要么全不做',body:'导入 24 道题，要执行 24 条 INSERT。如果导入到第 10 条时程序出错退出了，数据库里就只有一半的题；下次启动时检查“表里有数据”，就不会再导入了，题库永远缺一半。\n解决办法是把这 24 条 INSERT 放在一个“事务”里：先开始事务，执行所有插入，全部成功后“提交”（commit），数据才真正生效；中间任何一步出错就“回滚”（rollback），之前插入的也全部撤销，数据库回到开始前的样子。\n事务保证了一组操作“要么全做，要么全不做”，这就是事务的原子性。另外，SQLite 把很多条插入放在一个事务里，速度也比一条一条单独提交快得多。'},
  {title:'种子数据和数据库文件',body:'data/questions.json 这种“程序第一次运行时导入的初始数据”，叫种子数据（seed）。它是题库的源头，要提交到 Git 里；而 data/zixishi.db 是程序运行时生成的数据库文件，里面以后还会有用户的密码和学习记录，不应该提交。第 1 关建的 .gitignore 已经忽略了数据库文件，可以打开确认一下。\n数据库文件的位置也从环境变量 DB_PATH 读取，默认 data/zixishi.db。写自动化测试或者想从头再来时，换一个路径（或者直接删掉这个文件）就是一个全新的数据库，程序会重新建表、重新导入。\n想直接看数据库里的数据，可以装一个图形化工具：DB Browser for SQLite（免费）或者 IDEA、VS Code 的数据库插件，打开 data/zixishi.db，能看到表结构，还能直接写 SQL 查询。'},
  {title:'任务一：准备种子数据',body:'在项目根目录新建 data 文件夹，把下面的内容保存为 data/questions.json。这是题库的原始数据：一个 JSON 数组，每个元素是一道题，字段和第 3 关定好的题目格式完全一样。前 3 道就是原来写在代码里的那 3 道。\n这份数据是“资料”而不是代码，可以直接复制。以后想加题，改这个文件、删掉数据库文件再启动就行；第 16 关做好管理后台以后，就能在网页上加题了。',practice:{steps:['新建 data/questions.json，复制下面的内容，用 UTF-8 编码保存（VS Code 和 IDEA 默认就是 UTF-8）。','可以用浏览器或 VS Code 打开它检查一下：格式写错时 VS Code 会标红。'],expect:'data/questions.json 保存好，一共 24 道题'},code:`[
  {"id": 1, "category": "go", "title": "Go 的 defer 什么时候执行？", "answer": "在所在函数返回前执行，多个 defer 后进先出。", "difficulty": 1},
  {"id": 2, "category": "mysql", "title": "什么是联合索引的最左前缀原则？", "answer": "查询条件要从联合索引最左边的列开始用，才能用上索引。", "difficulty": 2},
  {"id": 3, "category": "go", "title": "goroutine 和线程有什么区别？", "answer": "goroutine 由 Go 运行时调度，栈很小，创建和切换都比线程便宜。", "difficulty": 2},
  {"id": 4, "category": "go", "title": "切片和数组有什么区别？", "answer": "数组长度固定，是值类型；切片是对底层数组的引用，可以动态增长。", "difficulty": 1},
  {"id": 5, "category": "go", "title": "map 可以在多个 goroutine 里同时写吗？", "answer": "不可以，并发写会直接报错退出，要加锁或者使用 sync.Map。", "difficulty": 2},
  {"id": 6, "category": "go", "title": "channel 有缓冲和无缓冲有什么区别？", "answer": "无缓冲的发送要等接收方就绪；有缓冲的在缓冲区没满时可以直接发送。", "difficulty": 2},
  {"id": 7, "category": "go", "title": "interface 的零值是什么？", "answer": "是 nil。只有类型和值都为空时，接口才等于 nil。", "difficulty": 2},
  {"id": 8, "category": "go", "title": "context 包主要用来做什么？", "answer": "在调用链之间传递取消信号、超时时间和请求范围内的数据。", "difficulty": 2},
  {"id": 9, "category": "go", "title": "new 和 make 有什么区别？", "answer": "new 分配内存并返回指针；make 只用于切片、map 和 channel，返回初始化好的值。", "difficulty": 1},
  {"id": 10, "category": "go", "title": "什么是 Go 的逃逸分析？", "answer": "编译器判断变量能否留在栈上，会被函数外部引用的变量就分配到堆上。", "difficulty": 3},
  {"id": 11, "category": "go", "title": "sync.WaitGroup 怎么用？", "answer": "启动任务前 Add，任务结束时 Done，主流程用 Wait 等待全部完成。", "difficulty": 1},
  {"id": 12, "category": "go", "title": "Go 的垃圾回收用的是什么算法？", "answer": "三色标记清除，配合写屏障，让大部分回收工作和程序并发进行。", "difficulty": 3},
  {"id": 13, "category": "mysql", "title": "InnoDB 和 MyISAM 有什么区别？", "answer": "InnoDB 支持事务、行锁和外键，MyISAM 都不支持，现在默认用 InnoDB。", "difficulty": 1},
  {"id": 14, "category": "mysql", "title": "事务的四个特性是什么？", "answer": "原子性、一致性、隔离性、持久性，合称 ACID。", "difficulty": 1},
  {"id": 15, "category": "mysql", "title": "为什么 InnoDB 用 B+ 树做索引？", "answer": "B+ 树又矮又胖，查询只要很少次磁盘读取，叶子节点相连方便范围查询。", "difficulty": 2},
  {"id": 16, "category": "mysql", "title": "什么是回表？", "answer": "用二级索引查到主键后，还要再到主键索引里取整行数据。", "difficulty": 2},
  {"id": 17, "category": "mysql", "title": "MySQL 默认的隔离级别是什么？", "answer": "可重复读（REPEATABLE READ）。", "difficulty": 1},
  {"id": 18, "category": "mysql", "title": "什么是慢查询，怎么排查？", "answer": "执行时间超过阈值的查询。开启慢查询日志，再用 EXPLAIN 看执行计划。", "difficulty": 2},
  {"id": 19, "category": "mysql", "title": "为什么不建议用 SELECT *？", "answer": "会读取用不到的列，增加传输量，还可能用不上覆盖索引。", "difficulty": 1},
  {"id": 20, "category": "redis", "title": "Redis 为什么这么快？", "answer": "数据在内存里，单线程处理命令没有锁竞争，并且使用 IO 多路复用。", "difficulty": 1},
  {"id": 21, "category": "redis", "title": "Redis 有哪几种常用数据类型？", "answer": "字符串、哈希、列表、集合、有序集合。", "difficulty": 1},
  {"id": 22, "category": "redis", "title": "什么是缓存穿透，怎么解决？", "answer": "查询根本不存在的数据，每次都打到数据库。可以缓存空值或使用布隆过滤器。", "difficulty": 2},
  {"id": 23, "category": "redis", "title": "RDB 和 AOF 有什么区别？", "answer": "RDB 定时保存整个内存快照；AOF 记录每条写命令，数据更完整但文件更大。", "difficulty": 2},
  {"id": 24, "category": "redis", "title": "怎么用 Redis 实现分布式锁？", "answer": "用 SET key value NX EX 加锁并设置过期时间，释放时检查 value 是自己的再删除。", "difficulty": 3}
]`,explain:[{at:'[',to:']',text:'方括号是 JSON 数组，里面每一对花括号是一道题：id 编号、category 科目、title 题目、answer 参考答案、difficulty 难度（1 简单、2 中等、3 难）。注意 JSON 的键和字符串都必须用双引号，最后一项后面不能有逗号。'}]},
  {title:'任务二：数据访问层改用数据库',body:'把数据访问层从“查内存里的列表”改成“执行 SQL 查数据库”：建表、导入种子数据、按科目查询、按编号查询。按你选的后端语言显示具体写法。',variants:{go:{practice:{steps:['在项目根目录运行 go get modernc.org/sqlite 安装驱动（会自动写进 go.mod）。','新建 data 文件夹，把上一张卡片的题库保存为 data/questions.json。','把 internal/store/store.go 整个换成下面的骨架，补完三个 TODO。','运行 go build ./... 会报错，因为 handler 和 main 还在用旧的写法，下一个任务改。'],expect:'go build ./internal/store/ 没有输出，说明数据访问层编译通过'},code:'package store\n\nimport (\n    "database/sql"\n    "encoding/json"\n    "errors"\n    "os"\n\n    _ "modernc.org/sqlite"\n)\n\ntype Question struct {\n    ID         int    `json:"id"`\n    Category   string `json:"category"`\n    Title      string `json:"title"`\n    Answer     string `json:"answer"`\n    Difficulty int    `json:"difficulty"`\n}\n\n// ErrNotFound 表示没找到。处理请求的层只认它，不用知道底层是什么数据库。\nvar ErrNotFound = errors.New("not found")\n\nconst schema = `CREATE TABLE IF NOT EXISTS questions (\n    id         INTEGER PRIMARY KEY,\n    category   TEXT    NOT NULL,\n    title      TEXT    NOT NULL,\n    answer     TEXT    NOT NULL,\n    difficulty INTEGER NOT NULL DEFAULT 1\n)`\n\nconst columns = "id, category, title, answer, difficulty"\n\ntype QuestionStore struct {\n    db *sql.DB\n}\n\n// Open 打开（不存在就创建）数据库文件，并建好表。\nfunc Open(path string) (*QuestionStore, error) {\n    db, err := sql.Open("sqlite", path)\n    if err != nil {\n        return nil, err\n    }\n    if _, err := db.Exec(schema); err != nil {\n        return nil, err\n    }\n    return &QuestionStore{db: db}, nil\n}\n\nfunc scanQuestion(row interface{ Scan(...any) error }) (Question, error) {\n    var q Question\n    err := row.Scan(&q.ID, &q.Category, &q.Title, &q.Answer, &q.Difficulty)\n    return q, err\n}\n\n// ImportIfEmpty 在表里还没有题目时，从 JSON 文件导入，返回导入的数量。\nfunc (s *QuestionStore) ImportIfEmpty(jsonPath string) (int, error) {\n    // TODO 1：用 s.db.QueryRow("SELECT COUNT(*) FROM questions").Scan(&n) 查出已有题数，大于 0 就返回 0, nil\n    // TODO 2：os.ReadFile 读文件，json.Unmarshal 解析成 []Question\n    // TODO 3：s.db.Begin() 开始事务，defer tx.Rollback()；逐个 tx.Exec 执行\n    //         INSERT INTO questions (id, category, title, answer, difficulty) VALUES (?, ?, ?, ?, ?)；\n    //         最后 tx.Commit()，返回导入的数量\n    return 0, nil\n}\n\n// List 返回某个科目的题目，按编号排序；category 为空时返回全部。\nfunc (s *QuestionStore) List(category string) ([]Question, error) {\n    rows, err := s.db.Query("SELECT "+columns+" FROM questions WHERE ? = \'\' OR category = ? ORDER BY id", category, category)\n    if err != nil {\n        return nil, err\n    }\n    defer rows.Close()\n    result := []Question{}\n    // TODO 4：for rows.Next() 循环，用 scanQuestion(rows) 读出每一行，追加到 result\n    return result, rows.Err()\n}\n\n// Get 按编号查找，找不到返回 ErrNotFound。\nfunc (s *QuestionStore) Get(id int) (Question, error) {\n    // TODO 5：用 s.db.QueryRow 查询 WHERE id = ?，交给 scanQuestion；\n    //         错误是 sql.ErrNoRows 时（用 errors.Is 判断）返回 ErrNotFound\n    return Question{}, nil\n}',explain:[{at:'package store',text:'还是 store 包，对外的用法尽量保持不变。'},{at:'import (',to:'_ "modernc.org/sqlite"',text:'database/sql 是 Go 标准库里操作数据库的通用接口，具体连哪种数据库由“驱动”决定。modernc.org/sqlite 是纯 Go 写的 SQLite 驱动，前面的下划线表示“只导入、不直接使用”：导入时它会把自己注册成名叫 sqlite 的驱动。'},{at:'type Question struct {',to:'Difficulty int    `json:"difficulty"`',text:'题目结构体不变。json 标签既用于返回接口，也用于读取 questions.json。'},{at:'var ErrNotFound = errors.New("not found")',text:'自己定义一个“没找到”的错误值。数据库驱动找不到数据时返回的是 sql.ErrNoRows，我们把它翻译成 ErrNotFound，处理请求的层就不用导入 database/sql 了。'},{at:'const schema = `CREATE TABLE IF NOT EXISTS questions (',to:')`',text:'建表语句，用反引号写多行字符串。id 是主键；NOT NULL 表示不能为空；DEFAULT 1 是不写时的默认值。'},{at:'const columns = "id, category, title, answer, difficulty"',text:'几个查询都要用到的列名，写成常量避免重复。注意不用 SELECT *：明确列出要哪几列，顺序也和后面 Scan 的顺序一一对应。'},{at:'type QuestionStore struct {',to:'db *sql.DB',text:'仓库里不再放题目切片，而是放一个数据库连接池 *sql.DB。'},{at:'func Open(path string) (*QuestionStore, error) {',to:'return &QuestionStore{db: db}, nil',text:'sql.Open 准备好连接池（文件不存在时第一次用到会自动创建），再执行建表语句。任何一步出错都把错误返回给调用方，由 main 决定怎么办。'},{at:'func scanQuestion(row interface{ Scan(...any) error }) (Question, error) {',to:'return q, err',text:'把一行查询结果读进 Question。Scan 按 SELECT 的列顺序，把每一列的值写进对应的变量（所以要传地址 &）。参数类型写成“任何有 Scan 方法的东西”，单行结果 *sql.Row 和多行结果 *sql.Rows 都能用。'},{at:'func (s *QuestionStore) ImportIfEmpty(jsonPath string) (int, error) {',to:'return 0, nil',text:'导入种子数据，要你补全。表里已经有题目就跳过，所以每次启动都调用它也没问题。'},{at:'func (s *QuestionStore) List(category string) ([]Question, error) {',text:'返回值多了一个 error：查数据库可能失败（比如文件损坏），要把错误交给调用方。'},{at:'rows, err := s.db.Query(',text:'执行查询，两个问号依次对应后面的两个 category。WHERE ? = \'\' OR category = ? 的意思是：参数为空时第一个条件成立，返回全部；否则按科目筛选。一条 SQL 就处理了两种情况。'},{at:'if err != nil {',to:'defer rows.Close()',text:'出错就返回；查询成功后用 defer 保证结果集最后会被关闭，否则连接会被一直占着。'},{at:'result := []Question{}',to:'return result, rows.Err()',text:'逐行读取要你补全。最后返回 rows.Err()：遍历过程中出的错要在这里检查。'},{at:'func (s *QuestionStore) Get(id int) (Question, error) {',to:'return Question{}, nil',text:'按编号查一行，要你补全。'}],solution:{code:'package store\n\nimport (\n    "database/sql"\n    "encoding/json"\n    "errors"\n    "os"\n\n    _ "modernc.org/sqlite"\n)\n\ntype Question struct {\n    ID         int    `json:"id"`\n    Category   string `json:"category"`\n    Title      string `json:"title"`\n    Answer     string `json:"answer"`\n    Difficulty int    `json:"difficulty"`\n}\n\n// ErrNotFound 表示没找到。处理请求的层只认它，不用知道底层是什么数据库。\nvar ErrNotFound = errors.New("not found")\n\nconst schema = `CREATE TABLE IF NOT EXISTS questions (\n    id         INTEGER PRIMARY KEY,\n    category   TEXT    NOT NULL,\n    title      TEXT    NOT NULL,\n    answer     TEXT    NOT NULL,\n    difficulty INTEGER NOT NULL DEFAULT 1\n)`\n\nconst columns = "id, category, title, answer, difficulty"\n\ntype QuestionStore struct {\n    db *sql.DB\n}\n\n// Open 打开（不存在就创建）数据库文件，并建好表。\nfunc Open(path string) (*QuestionStore, error) {\n    db, err := sql.Open("sqlite", path)\n    if err != nil {\n        return nil, err\n    }\n    if _, err := db.Exec(schema); err != nil {\n        return nil, err\n    }\n    return &QuestionStore{db: db}, nil\n}\n\nfunc scanQuestion(row interface{ Scan(...any) error }) (Question, error) {\n    var q Question\n    err := row.Scan(&q.ID, &q.Category, &q.Title, &q.Answer, &q.Difficulty)\n    return q, err\n}\n\n// ImportIfEmpty 在表里还没有题目时，从 JSON 文件导入，返回导入的数量。\nfunc (s *QuestionStore) ImportIfEmpty(jsonPath string) (int, error) {\n    var n int\n    if err := s.db.QueryRow("SELECT COUNT(*) FROM questions").Scan(&n); err != nil {\n        return 0, err\n    }\n    if n > 0 {\n        return 0, nil\n    }\n    data, err := os.ReadFile(jsonPath)\n    if err != nil {\n        return 0, err\n    }\n    var items []Question\n    if err := json.Unmarshal(data, &items); err != nil {\n        return 0, err\n    }\n    tx, err := s.db.Begin()\n    if err != nil {\n        return 0, err\n    }\n    defer tx.Rollback()\n    for _, q := range items {\n        _, err := tx.Exec("INSERT INTO questions ("+columns+") VALUES (?, ?, ?, ?, ?)",\n            q.ID, q.Category, q.Title, q.Answer, q.Difficulty)\n        if err != nil {\n            return 0, err\n        }\n    }\n    return len(items), tx.Commit()\n}\n\n// List 返回某个科目的题目，按编号排序；category 为空时返回全部。\nfunc (s *QuestionStore) List(category string) ([]Question, error) {\n    rows, err := s.db.Query("SELECT "+columns+" FROM questions WHERE ? = \'\' OR category = ? ORDER BY id", category, category)\n    if err != nil {\n        return nil, err\n    }\n    defer rows.Close()\n    result := []Question{}\n    for rows.Next() {\n        q, err := scanQuestion(rows)\n        if err != nil {\n            return nil, err\n        }\n        result = append(result, q)\n    }\n    return result, rows.Err()\n}\n\n// Get 按编号查找，找不到返回 ErrNotFound。\nfunc (s *QuestionStore) Get(id int) (Question, error) {\n    q, err := scanQuestion(s.db.QueryRow("SELECT "+columns+" FROM questions WHERE id = ?", id))\n    if errors.Is(err, sql.ErrNoRows) {\n        return Question{}, ErrNotFound\n    }\n    return q, err\n}',explain:[{at:'package store',text:'还是 store 包，对外的用法尽量保持不变。'},{at:'import (',to:'_ "modernc.org/sqlite"',text:'database/sql 是 Go 标准库里操作数据库的通用接口，具体连哪种数据库由“驱动”决定。modernc.org/sqlite 是纯 Go 写的 SQLite 驱动，前面的下划线表示“只导入、不直接使用”：导入时它会把自己注册成名叫 sqlite 的驱动。'},{at:'type Question struct {',to:'Difficulty int    `json:"difficulty"`',text:'题目结构体不变。json 标签既用于返回接口，也用于读取 questions.json。'},{at:'var ErrNotFound = errors.New("not found")',text:'自己定义一个“没找到”的错误值。数据库驱动找不到数据时返回的是 sql.ErrNoRows，我们把它翻译成 ErrNotFound，处理请求的层就不用导入 database/sql 了。'},{at:'const schema = `CREATE TABLE IF NOT EXISTS questions (',to:')`',text:'建表语句，用反引号写多行字符串。id 是主键；NOT NULL 表示不能为空；DEFAULT 1 是不写时的默认值。'},{at:'const columns = "id, category, title, answer, difficulty"',text:'几个查询都要用到的列名，写成常量避免重复。注意不用 SELECT *：明确列出要哪几列，顺序也和后面 Scan 的顺序一一对应。'},{at:'type QuestionStore struct {',to:'db *sql.DB',text:'仓库里不再放题目切片，而是放一个数据库连接池 *sql.DB。'},{at:'func Open(path string) (*QuestionStore, error) {',to:'return &QuestionStore{db: db}, nil',text:'sql.Open 准备好连接池（文件不存在时第一次用到会自动创建），再执行建表语句。任何一步出错都把错误返回给调用方，由 main 决定怎么办。'},{at:'func scanQuestion(row interface{ Scan(...any) error }) (Question, error) {',to:'return q, err',text:'把一行查询结果读进 Question。Scan 按 SELECT 的列顺序，把每一列的值写进对应的变量（所以要传地址 &）。参数类型写成“任何有 Scan 方法的东西”，单行结果 *sql.Row 和多行结果 *sql.Rows 都能用。'},{at:'func (s *QuestionStore) ImportIfEmpty(jsonPath string) (int, error) {',text:'导入种子数据。'},{at:'var n int',to:'return 0, nil',text:'先数一数表里有几道题。QueryRow 用于只返回一行的查询，Scan 把结果写进 n。已经有题目就什么都不做。'},{at:'data, err := os.ReadFile(jsonPath)',to:'return 0, err',text:'读出整个 JSON 文件，解析成题目切片。'},{at:'var items []Question',to:'return 0, err',text:'json.Unmarshal 按 json 标签把每个字段填进结构体。'},{at:'tx, err := s.db.Begin()',to:'defer tx.Rollback()',text:'开始事务。defer tx.Rollback() 是保险：中途 return 时自动回滚；如果已经 Commit 成功，再 Rollback 不会有任何效果。'},{at:'for _, q := range items {',to:'q.ID, q.Category, q.Title, q.Answer, q.Difficulty)',text:'在事务里逐条插入，每个值都通过占位符传入。'},{at:'if err != nil {',to:'return 0, err',text:'任何一条失败就返回，defer 会回滚之前插入的数据。'},{at:'return len(items), tx.Commit()',text:'全部成功才提交，返回导入数量和提交结果。'},{at:'func (s *QuestionStore) List(category string) ([]Question, error) {',text:'返回值多了 error。'},{at:'rows, err := s.db.Query(',text:'执行查询，参数为空返回全部，否则按科目筛选。'},{at:'if err != nil {',to:'defer rows.Close()',text:'出错就返回；记得关闭结果集。'},{at:'result := []Question{}',text:'先准备空切片，没有数据时返回 [] 而不是 null。'},{at:'for rows.Next() {',to:'result = append(result, q)',text:'Next 移到下一行，没有更多行时返回 false 结束循环。每一行都读成 Question 追加进结果。'},{at:'return result, rows.Err()',text:'检查遍历过程中有没有出错。'},{at:'func (s *QuestionStore) Get(id int) (Question, error) {',to:'q, err := scanQuestion(s.db.QueryRow(',text:'按主键查询一行。'},{at:'if errors.Is(err, sql.ErrNoRows) {',to:'return Question{}, ErrNotFound',text:'没有这一行时驱动返回 sql.ErrNoRows，翻译成我们自己的 ErrNotFound。'},{at:'return q, err',text:'其他情况原样返回：成功时 err 是 nil，数据库出错时交给调用方。'}]}},java:{body:'Java 用 Spring 的 JdbcTemplate 执行 SQL，SQLite 驱动是 sqlite-jdbc。要做四件事：加依赖；配置数据库地址；写建表语句 schema.sql（Spring Boot 启动时会自动执行）；把仓库改成查数据库，并写一个启动时导入种子数据的组件。\n仓库的 findAll、findById 方法名和返回类型都不变，所以控制器一行都不用改：Optional 为空时照样返回 404；数据库出错会抛出异常，被第 4 关写的 GlobalErrors 接住，返回 500。\nJdbcTemplate 常用的方法：query(SQL, RowMapper, 参数…) 返回对象列表；queryForObject(SQL, 类型) 返回单个值；batchUpdate 批量执行插入。参数按顺序对应 SQL 里的 ?。',practice:{steps:['按代码第一部分修改 pom.xml（点 Load Maven Changes）和 application.properties，新建 src/main/resources/schema.sql。','在项目根目录新建 data 文件夹，把题库保存为 data/questions.json。','把 QuestionRepository.java 换成第二部分，补完 TODO。','新建 config/DataImporter.java（第三部分），补完 TODO。','运行 mvnw spring-boot:run，第一次会看到“导入了 24 道题”，项目里多出 data/zixishi.db。重启一次，不会再导入。'],expect:'... 导入了 24 道题\n... Tomcat started on port 8080 (http) ...'},code:'<!-- pom.xml 的 <dependencies> 里加上 -->\n<dependency>\n    <groupId>org.springframework.boot</groupId>\n    <artifactId>spring-boot-starter-jdbc</artifactId>\n</dependency>\n<dependency>\n    <groupId>org.xerial</groupId>\n    <artifactId>sqlite-jdbc</artifactId>\n</dependency>\n\n# application.properties 里加上\nspring.datasource.url=jdbc:sqlite:${DB_PATH:data/zixishi.db}\nspring.datasource.hikari.maximum-pool-size=1\nspring.sql.init.mode=always\n\n-- src/main/resources/schema.sql\nCREATE TABLE IF NOT EXISTS questions (\n    id         INTEGER PRIMARY KEY,\n    category   TEXT    NOT NULL,\n    title      TEXT    NOT NULL,\n    answer     TEXT    NOT NULL,\n    difficulty INTEGER NOT NULL DEFAULT 1\n);\n\n// repository/QuestionRepository.java\npackage com.example.zixishi.repository;\n\nimport com.example.zixishi.model.Question;\nimport java.util.List;\nimport java.util.Optional;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.jdbc.core.RowMapper;\nimport org.springframework.stereotype.Repository;\n\n@Repository\npublic class QuestionRepository {\n\n    private static final String COLUMNS = "id, category, title, answer, difficulty";\n    private static final RowMapper<Question> MAPPER = (rs, i) -> new Question(\n        rs.getInt("id"), rs.getString("category"), rs.getString("title"),\n        rs.getString("answer"), rs.getInt("difficulty"));\n\n    private final JdbcTemplate jdbc;\n\n    public QuestionRepository(JdbcTemplate jdbc) {\n        this.jdbc = jdbc;\n    }\n\n    public List<Question> findAll(String category) {\n        // TODO 1：category 为 null 时当作 ""；用 jdbc.query 执行\n        //         SELECT 列 FROM questions WHERE ? = \'\' OR category = ? ORDER BY id，参数是两次 category\n        return List.of();\n    }\n\n    public Optional<Question> findById(int id) {\n        // TODO 2：用 jdbc.query 查 WHERE id = ?，得到列表后 .stream().findFirst()\n        return Optional.empty();\n    }\n\n    public int count() {\n        return jdbc.queryForObject("SELECT COUNT(*) FROM questions", Integer.class);\n    }\n\n    public void insertAll(List<Question> items) {\n        // TODO 3：用 jdbc.batchUpdate(SQL, items, items.size(), (ps, q) -> {...}) 批量插入，\n        //         在 lambda 里用 ps.setInt / ps.setString 依次设置 5 个 ? 的值（从 1 开始数）\n    }\n}\n\n// config/DataImporter.java\npackage com.example.zixishi.config;\n\nimport com.example.zixishi.model.Question;\nimport com.example.zixishi.repository.QuestionRepository;\nimport java.io.File;\nimport java.util.List;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.boot.ApplicationArguments;\nimport org.springframework.boot.ApplicationRunner;\nimport org.springframework.stereotype.Component;\nimport org.springframework.transaction.annotation.Transactional;\nimport tools.jackson.core.type.TypeReference;\nimport tools.jackson.databind.ObjectMapper;\n\n@Component\npublic class DataImporter implements ApplicationRunner {\n\n    private static final Logger log = LoggerFactory.getLogger(DataImporter.class);\n    private final QuestionRepository repo;\n    private final ObjectMapper mapper;\n\n    public DataImporter(QuestionRepository repo, ObjectMapper mapper) {\n        this.repo = repo;\n        this.mapper = mapper;\n    }\n\n    @Override\n    @Transactional\n    public void run(ApplicationArguments args) throws Exception {\n        // TODO 4：repo.count() 大于 0 就直接返回\n        // TODO 5：用 mapper.readValue(new File("data/questions.json"), new TypeReference<List<Question>>() {}) 读出题目，\n        //         调用 repo.insertAll，再用 log.info 打印“导入了 N 道题”\n    }\n}',explain:[{at:'<!-- pom.xml 的 <dependencies> 里加上 -->',to:'<artifactId>sqlite-jdbc</artifactId>',text:'两个依赖：spring-boot-starter-jdbc 提供 JdbcTemplate（执行 SQL 的工具）和连接池；sqlite-jdbc 是 SQLite 的驱动。'},{at:'<artifactId>sqlite-jdbc</artifactId>',to:'</dependency>',text:'JDBC 是 Java 访问数据库的标准接口，换数据库就是换驱动。两个依赖的版本都由 Spring Boot 管理，不用写版本号。改完点 Load Maven Changes。'},{at:'spring.datasource.url=jdbc:sqlite:${DB_PATH:data/zixishi.db}',text:'数据库地址：jdbc:sqlite: 后面是文件路径，从环境变量 DB_PATH 读取，默认 data/zixishi.db。'},{at:'spring.datasource.hikari.maximum-pool-size=1',text:'连接池最多一个连接。SQLite 同一时间只允许一个连接写入，只用一个连接可以避免“数据库被锁住”的错误。'},{at:'spring.sql.init.mode=always',text:'让 Spring Boot 每次启动都执行 resources 里的 schema.sql（默认只对内存数据库执行）。'},{at:'-- src/main/resources/schema.sql',to:');',text:'建表语句，-- 开头的是 SQL 注释。IF NOT EXISTS 让它每次启动都能安全执行。'},{at:'// repository/QuestionRepository.java',to:'import org.springframework.stereotype.Repository;',text:'仓库改成查数据库。JdbcTemplate 执行 SQL，RowMapper 把一行结果变成一个对象。'},{at:'@Repository',to:'public class QuestionRepository {',text:'仓库类，和以前一样由 Spring 创建和管理。'},{at:'private static final String COLUMNS',text:'要查询的列。不用 SELECT *，明确写出需要哪几列。'},{at:'private static final RowMapper<Question> MAPPER = (rs, i) -> new Question(',to:'rs.getString("answer"), rs.getInt("difficulty"));',text:'RowMapper 是一个“怎么把一行变成对象”的函数：rs 是当前行，按列名取出值，创建 Question。i 是行号，这里用不到。'},{at:'private final JdbcTemplate jdbc;',to:'this.jdbc = jdbc;',text:'通过构造函数拿到 Spring 自动配置好的 JdbcTemplate。原来写死的题目列表删掉了。'},{at:'public List<Question> findAll(String category) {',to:'return List.of();',text:'按科目查题目，要你补全。'},{at:'public Optional<Question> findById(int id) {',to:'return Optional.empty();',text:'按编号查一道题，要你补全。'},{at:'public int count() {',to:'return jdbc.queryForObject("SELECT COUNT(*) FROM questions", Integer.class);',text:'数一数表里有几道题。queryForObject 返回单个值，第二个参数说明结果的类型。'},{at:'public void insertAll(List<Question> items) {',text:'批量插入，要你补全。'},{at:'// config/DataImporter.java',to:'import tools.jackson.databind.ObjectMapper;',text:'新建一个启动时导入种子数据的组件。ObjectMapper 是 Spring Boot 自带的 JSON 工具 Jackson。Spring Boot 4 用的是 Jackson 3，包名以 tools.jackson 开头；如果你的项目是 Spring Boot 3，把这两行的 tools.jackson 换成 com.fasterxml.jackson。'},{at:'@Component',to:'public class DataImporter implements ApplicationRunner {',text:'实现 ApplicationRunner 接口的组件，Spring Boot 启动完成后会自动调用它的 run 方法。'},{at:'private static final Logger log',to:'this.mapper = mapper;',text:'日志记录器，以及通过构造函数注入的仓库和 JSON 工具。'},{at:'@Override',to:'public void run(ApplicationArguments args) throws Exception {',text:'@Transactional 让整个方法在一个事务里执行：全部成功才提交，抛出异常就全部回滚。要你补全。'}],solution:{code:'<!-- pom.xml 的 <dependencies> 里加上 -->\n<dependency>\n    <groupId>org.springframework.boot</groupId>\n    <artifactId>spring-boot-starter-jdbc</artifactId>\n</dependency>\n<dependency>\n    <groupId>org.xerial</groupId>\n    <artifactId>sqlite-jdbc</artifactId>\n</dependency>\n\n# application.properties 里加上\nspring.datasource.url=jdbc:sqlite:${DB_PATH:data/zixishi.db}\nspring.datasource.hikari.maximum-pool-size=1\nspring.sql.init.mode=always\n\n-- src/main/resources/schema.sql\nCREATE TABLE IF NOT EXISTS questions (\n    id         INTEGER PRIMARY KEY,\n    category   TEXT    NOT NULL,\n    title      TEXT    NOT NULL,\n    answer     TEXT    NOT NULL,\n    difficulty INTEGER NOT NULL DEFAULT 1\n);\n\n// repository/QuestionRepository.java\npackage com.example.zixishi.repository;\n\nimport com.example.zixishi.model.Question;\nimport java.util.List;\nimport java.util.Optional;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.jdbc.core.RowMapper;\nimport org.springframework.stereotype.Repository;\n\n@Repository\npublic class QuestionRepository {\n\n    private static final String COLUMNS = "id, category, title, answer, difficulty";\n    private static final RowMapper<Question> MAPPER = (rs, i) -> new Question(\n        rs.getInt("id"), rs.getString("category"), rs.getString("title"),\n        rs.getString("answer"), rs.getInt("difficulty"));\n\n    private final JdbcTemplate jdbc;\n\n    public QuestionRepository(JdbcTemplate jdbc) {\n        this.jdbc = jdbc;\n    }\n\n    public List<Question> findAll(String category) {\n        String c = category == null ? "" : category;\n        return jdbc.query("SELECT " + COLUMNS + " FROM questions WHERE ? = \'\' OR category = ? ORDER BY id",\n            MAPPER, c, c);\n    }\n\n    public Optional<Question> findById(int id) {\n        return jdbc.query("SELECT " + COLUMNS + " FROM questions WHERE id = ?", MAPPER, id)\n            .stream().findFirst();\n    }\n\n    public int count() {\n        return jdbc.queryForObject("SELECT COUNT(*) FROM questions", Integer.class);\n    }\n\n    public void insertAll(List<Question> items) {\n        jdbc.batchUpdate("INSERT INTO questions (" + COLUMNS + ") VALUES (?, ?, ?, ?, ?)", items, items.size(),\n            (ps, q) -> {\n                ps.setInt(1, q.id());\n                ps.setString(2, q.category());\n                ps.setString(3, q.title());\n                ps.setString(4, q.answer());\n                ps.setInt(5, q.difficulty());\n            });\n    }\n}\n\n// config/DataImporter.java\npackage com.example.zixishi.config;\n\nimport com.example.zixishi.model.Question;\nimport com.example.zixishi.repository.QuestionRepository;\nimport java.io.File;\nimport java.util.List;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.boot.ApplicationArguments;\nimport org.springframework.boot.ApplicationRunner;\nimport org.springframework.stereotype.Component;\nimport org.springframework.transaction.annotation.Transactional;\nimport tools.jackson.core.type.TypeReference;\nimport tools.jackson.databind.ObjectMapper;\n\n@Component\npublic class DataImporter implements ApplicationRunner {\n\n    private static final Logger log = LoggerFactory.getLogger(DataImporter.class);\n    private final QuestionRepository repo;\n    private final ObjectMapper mapper;\n\n    public DataImporter(QuestionRepository repo, ObjectMapper mapper) {\n        this.repo = repo;\n        this.mapper = mapper;\n    }\n\n    @Override\n    @Transactional\n    public void run(ApplicationArguments args) throws Exception {\n        if (repo.count() > 0) {\n            return;\n        }\n        List<Question> items = mapper.readValue(new File("data/questions.json"), new TypeReference<>() {});\n        repo.insertAll(items);\n        log.info("导入了 {} 道题", items.size());\n    }\n}',explain:[{at:'<!-- pom.xml 的 <dependencies> 里加上 -->',to:'<artifactId>sqlite-jdbc</artifactId>',text:'两个依赖：spring-boot-starter-jdbc 提供 JdbcTemplate（执行 SQL 的工具）和连接池；sqlite-jdbc 是 SQLite 的驱动。'},{at:'<artifactId>sqlite-jdbc</artifactId>',to:'</dependency>',text:'JDBC 是 Java 访问数据库的标准接口，换数据库就是换驱动。两个依赖的版本都由 Spring Boot 管理，不用写版本号。改完点 Load Maven Changes。'},{at:'spring.datasource.url=jdbc:sqlite:${DB_PATH:data/zixishi.db}',text:'数据库地址：jdbc:sqlite: 后面是文件路径，从环境变量 DB_PATH 读取，默认 data/zixishi.db。'},{at:'spring.datasource.hikari.maximum-pool-size=1',text:'连接池最多一个连接。SQLite 同一时间只允许一个连接写入，只用一个连接可以避免“数据库被锁住”的错误。'},{at:'spring.sql.init.mode=always',text:'让 Spring Boot 每次启动都执行 resources 里的 schema.sql（默认只对内存数据库执行）。'},{at:'-- src/main/resources/schema.sql',to:');',text:'建表语句，-- 开头的是 SQL 注释。IF NOT EXISTS 让它每次启动都能安全执行。'},{at:'// repository/QuestionRepository.java',to:'import org.springframework.stereotype.Repository;',text:'仓库改成查数据库。JdbcTemplate 执行 SQL，RowMapper 把一行结果变成一个对象。'},{at:'@Repository',to:'public class QuestionRepository {',text:'仓库类，和以前一样由 Spring 创建和管理。'},{at:'private static final String COLUMNS',text:'要查询的列。不用 SELECT *，明确写出需要哪几列。'},{at:'private static final RowMapper<Question> MAPPER = (rs, i) -> new Question(',to:'rs.getString("answer"), rs.getInt("difficulty"));',text:'RowMapper 是一个“怎么把一行变成对象”的函数：rs 是当前行，按列名取出值，创建 Question。i 是行号，这里用不到。'},{at:'private final JdbcTemplate jdbc;',to:'this.jdbc = jdbc;',text:'通过构造函数拿到 Spring 自动配置好的 JdbcTemplate。原来写死的题目列表删掉了。'},{at:'public List<Question> findAll(String category) {',to:'MAPPER, c, c);',text:'没传科目时 category 是 null，换成空字符串。参数为空时 ? = \'\' 成立，返回全部；否则按科目筛选。两个 ? 依次对应两个 c。'},{at:'public Optional<Question> findById(int id) {',to:'.stream().findFirst();',text:'按主键查询得到一个列表（0 或 1 个元素），findFirst 取出第一个，没有就是空的 Optional。'},{at:'public int count() {',to:'return jdbc.queryForObject("SELECT COUNT(*) FROM questions", Integer.class);',text:'数一数表里有几道题。'},{at:'public void insertAll(List<Question> items) {',to:'(ps, q) -> {',text:'batchUpdate 把一组数据用同一条 SQL 批量执行。参数依次是：SQL、数据列表、每批多少条、怎么给每条设置参数。'},{at:'ps.setInt(1, q.id());',to:'ps.setInt(5, q.difficulty());',text:'ps 是准备好的语句，按位置（从 1 开始）给每个 ? 设置值。'},{at:'// config/DataImporter.java',to:'import tools.jackson.databind.ObjectMapper;',text:'新建一个启动时导入种子数据的组件。ObjectMapper 是 Spring Boot 自带的 JSON 工具 Jackson。Spring Boot 4 用的是 Jackson 3，包名以 tools.jackson 开头；如果你的项目是 Spring Boot 3，把这两行的 tools.jackson 换成 com.fasterxml.jackson。'},{at:'@Component',to:'public class DataImporter implements ApplicationRunner {',text:'实现 ApplicationRunner 接口的组件，Spring Boot 启动完成后会自动调用它的 run 方法。'},{at:'private static final Logger log',to:'this.mapper = mapper;',text:'日志记录器，以及通过构造函数注入的仓库和 JSON 工具。'},{at:'@Override',to:'public void run(ApplicationArguments args) throws Exception {',text:'启动完成后自动执行，整个方法在一个事务里。'},{at:'if (repo.count() > 0) {',to:'return;',text:'已经有题目就跳过。'},{at:'List<Question> items = mapper.readValue(',text:'读出 JSON 文件，转成 Question 列表。TypeReference<>() {} 用来告诉 Jackson 目标类型是“Question 的列表”。'},{at:'repo.insertAll(items);',to:'log.info("导入了 {} 道题", items.size());',text:'批量插入，打印导入数量。'}]}},node:{body:'Node.js 用 better-sqlite3 操作 SQLite。分两个文件：database.js 负责打开数据库、建表、导入种子数据；questions.js 还是题目的数据访问层，函数名和参数都不变，只是里面改成执行 SQL。\n好消息是：better-sqlite3 是同步的，查不到时 get() 返回 undefined，出错时直接抛出异常。所以路由层一行都不用改：没找到照样返回 404，出错会被第 4 关写的错误处理中间件接住，返回 500。\nbetter-sqlite3 的用法：db.prepare(SQL) 先把 SQL “准备”好，得到一个语句对象；.all(参数…) 返回所有行（数组），.get(参数…) 返回第一行，.run(参数…) 执行插入、修改这类不返回行的语句。参数可以按顺序对应 ?，也可以传一个对象，对应 @名字 这样的命名占位符。',practice:{steps:['运行 npm install better-sqlite3 安装依赖。','新建 data 文件夹，把题库保存为 data/questions.json。','新建 src/db/database.js（代码第一部分），把 src/db/questions.js 换成第二部分，补完 TODO。','按最后一部分修改 app.js。','运行 node --watch app.js，第一次会看到“导入了 24 道题”，项目里多出 data/zixishi.db。重启一次，不会再导入。'],expect:'导入了 24 道题\n服务已启动：http://localhost:8080'},code:'// src/db/database.js\nconst Database = require("better-sqlite3");\nconst fs = require("node:fs");\nconst path = require("node:path");\n\nconst dbPath = process.env.DB_PATH || "data/zixishi.db";\nfs.mkdirSync(path.dirname(dbPath), { recursive: true });\nconst db = new Database(dbPath);\n\ndb.exec(`CREATE TABLE IF NOT EXISTS questions (\n  id         INTEGER PRIMARY KEY,\n  category   TEXT    NOT NULL,\n  title      TEXT    NOT NULL,\n  answer     TEXT    NOT NULL,\n  difficulty INTEGER NOT NULL DEFAULT 1\n)`);\n\n// 表里还没有题目时，从 JSON 文件导入，返回导入的数量\nfunction importIfEmpty(jsonPath) {\n  // TODO 1：用 db.prepare("SELECT COUNT(*) AS n FROM questions").get() 查出已有题数，大于 0 就返回 0\n  // TODO 2：fs.readFileSync(jsonPath, "utf8") 读文件，JSON.parse 解析成数组\n  // TODO 3：准备 INSERT 语句（用 @id、@category 这样的命名占位符），\n  //         用 db.transaction 包一个“逐条插入”的函数，调用它，最后返回数组长度\n}\n\nmodule.exports = { db, importIfEmpty };\n\n// src/db/questions.js\nconst { db } = require("./database");\n\nconst COLUMNS = "id, category, title, answer, difficulty";\n\nfunction listQuestions(category) {\n  // TODO 4：执行 SELECT ${COLUMNS} FROM questions WHERE ? = \'\' OR category = ? ORDER BY id，返回所有行\n}\n\nfunction getQuestion(id) {\n  // TODO 5：执行 SELECT ${COLUMNS} FROM questions WHERE id = ?，返回第一行（没有时是 undefined）\n}\n\nmodule.exports = { listQuestions, getQuestion };\n\n// app.js：在 app.listen 前面加上这几行（顶部记得导入）\nconst { importIfEmpty } = require("./src/db/database");\n\nconst imported = importIfEmpty("data/questions.json");\nif (imported > 0) {\n  console.log(`导入了 ${imported} 道题`);\n}',explain:[{at:'// src/db/database.js',to:'const path = require("node:path");',text:'better-sqlite3 是 Node.js 最常用的 SQLite 库，它的方法都是同步的（直接返回结果，不用 await），写起来最简单。node:fs 读写文件，node:path 处理路径。'},{at:'const dbPath = process.env.DB_PATH || "data/zixishi.db";',text:'数据库文件的位置从环境变量读取，默认 data/zixishi.db。'},{at:'fs.mkdirSync(path.dirname(dbPath), { recursive: true });',text:'先确保文件所在的文件夹存在。path.dirname 取出路径里的文件夹部分；recursive: true 表示已经存在也不报错。'},{at:'const db = new Database(dbPath);',text:'打开数据库文件，不存在就创建。整个程序共用这一个连接。'},{at:'db.exec(`CREATE TABLE IF NOT EXISTS questions (',to:')`);',text:'执行建表语句。id 是主键；NOT NULL 表示不能为空；DEFAULT 1 是不写时的默认值。IF NOT EXISTS 让它每次启动都能安全执行。'},{at:'function importIfEmpty(jsonPath) {',text:'导入种子数据，要你补全。'},{at:'module.exports = { db, importIfEmpty };',text:'导出连接和导入函数。'},{at:'// src/db/questions.js',to:'const { db } = require("./database");',text:'题目的数据访问层改成查数据库，从 database.js 拿到连接。'},{at:'const COLUMNS = "id, category, title, answer, difficulty";',text:'要查询的列。不用 SELECT *，明确写出需要哪几列。'},{at:'function listQuestions(category) {',text:'按科目查题目，要你补全。'},{at:'function getQuestion(id) {',text:'按编号查一道题，要你补全。'},{at:'module.exports = { listQuestions, getQuestion };',text:'导出的函数和以前一样，路由层不用改。'},{at:'// app.js',to:'const { importIfEmpty } = require("./src/db/database");',text:'入口导入 importIfEmpty。'},{at:'const imported = importIfEmpty("data/questions.json");',to:'console.log(`导入了 ${imported} 道题`);',text:'启动服务前先导入种子数据。出错时这里会抛出异常，程序直接退出并打印原因：数据库都没准备好，服务也没法工作。'}],solution:{code:'// src/db/database.js\nconst Database = require("better-sqlite3");\nconst fs = require("node:fs");\nconst path = require("node:path");\n\nconst dbPath = process.env.DB_PATH || "data/zixishi.db";\nfs.mkdirSync(path.dirname(dbPath), { recursive: true });\nconst db = new Database(dbPath);\n\ndb.exec(`CREATE TABLE IF NOT EXISTS questions (\n  id         INTEGER PRIMARY KEY,\n  category   TEXT    NOT NULL,\n  title      TEXT    NOT NULL,\n  answer     TEXT    NOT NULL,\n  difficulty INTEGER NOT NULL DEFAULT 1\n)`);\n\nfunction importIfEmpty(jsonPath) {\n  const { n } = db.prepare("SELECT COUNT(*) AS n FROM questions").get();\n  if (n > 0) return 0;\n  const items = JSON.parse(fs.readFileSync(jsonPath, "utf8"));\n  const insert = db.prepare(\n    "INSERT INTO questions (id, category, title, answer, difficulty) VALUES (@id, @category, @title, @answer, @difficulty)"\n  );\n  const insertAll = db.transaction((rows) => {\n    for (const q of rows) insert.run(q);\n  });\n  insertAll(items);\n  return items.length;\n}\n\nmodule.exports = { db, importIfEmpty };\n\n// src/db/questions.js\nconst { db } = require("./database");\n\nconst COLUMNS = "id, category, title, answer, difficulty";\n\nfunction listQuestions(category) {\n  const c = category || "";\n  return db\n    .prepare(`SELECT ${COLUMNS} FROM questions WHERE ? = \'\' OR category = ? ORDER BY id`)\n    .all(c, c);\n}\n\nfunction getQuestion(id) {\n  return db.prepare(`SELECT ${COLUMNS} FROM questions WHERE id = ?`).get(id);\n}\n\nmodule.exports = { listQuestions, getQuestion };\n\n// app.js：在 app.listen 前面加上这几行（顶部记得导入）\nconst { importIfEmpty } = require("./src/db/database");\n\nconst imported = importIfEmpty("data/questions.json");\nif (imported > 0) {\n  console.log(`导入了 ${imported} 道题`);\n}',explain:[{at:'// src/db/database.js',to:'const path = require("node:path");',text:'better-sqlite3 是 Node.js 最常用的 SQLite 库，它的方法都是同步的（直接返回结果，不用 await），写起来最简单。node:fs 读写文件，node:path 处理路径。'},{at:'const dbPath = process.env.DB_PATH || "data/zixishi.db";',text:'数据库文件的位置从环境变量读取，默认 data/zixishi.db。'},{at:'fs.mkdirSync(path.dirname(dbPath), { recursive: true });',text:'先确保文件所在的文件夹存在。path.dirname 取出路径里的文件夹部分；recursive: true 表示已经存在也不报错。'},{at:'const db = new Database(dbPath);',text:'打开数据库文件，不存在就创建。整个程序共用这一个连接。'},{at:'db.exec(`CREATE TABLE IF NOT EXISTS questions (',to:')`);',text:'执行建表语句。id 是主键；NOT NULL 表示不能为空；DEFAULT 1 是不写时的默认值。IF NOT EXISTS 让它每次启动都能安全执行。'},{at:'function importIfEmpty(jsonPath) {',text:'导入种子数据。'},{at:'const { n } = db.prepare("SELECT COUNT(*) AS n FROM questions").get();',to:'if (n > 0) return 0;',text:'数一数表里有几道题。AS n 给结果列起名，get() 返回 { n: 数量 }，用解构直接取出来。已经有题目就跳过。'},{at:'const items = JSON.parse(fs.readFileSync(jsonPath, "utf8"));',text:'读出 JSON 文件并解析成数组。'},{at:'const insert = db.prepare(',to:');',text:'准备插入语句。@id 这样的命名占位符会从传入对象的同名属性里取值，正好和 JSON 里的字段对应。'},{at:'const insertAll = db.transaction((rows) => {',to:'});',text:'db.transaction 把一个函数包装成“在事务里执行”：全部成功才提交，中途抛出异常就全部回滚。'},{at:'insertAll(items);',to:'return items.length;',text:'执行导入，返回数量。'},{at:'module.exports = { db, importIfEmpty };',text:'导出。'},{at:'// src/db/questions.js',to:'const { db } = require("./database");',text:'题目的数据访问层改成查数据库，从 database.js 拿到连接。'},{at:'const COLUMNS = "id, category, title, answer, difficulty";',text:'要查询的列。不用 SELECT *，明确写出需要哪几列。'},{at:'function listQuestions(category) {',to:'const c = category || "";',text:'没传科目时 category 是 undefined，统一换成空字符串。'},{at:'return db',to:'.all(c, c);',text:'参数为空时 ? = \'\' 成立，返回全部；否则按科目筛选。两个 ? 依次对应两个 c。all 返回所有行组成的数组，每一行是一个对象，键就是列名，正好是接口要的格式。'},{at:'function getQuestion(id) {',to:'return db.prepare(`SELECT ${COLUMNS} FROM questions WHERE id = ?`).get(id);',text:'按主键查一行，没有时 get 返回 undefined，路由层据此返回 404。'},{at:'module.exports = { listQuestions, getQuestion };',text:'导出。'},{at:'// app.js',to:'const { importIfEmpty } = require("./src/db/database");',text:'入口导入 importIfEmpty。'},{at:'const imported = importIfEmpty("data/questions.json");',to:'console.log(`导入了 ${imported} 道题`);',text:'启动服务前先导入种子数据。出错时这里会抛出异常，程序直接退出并打印原因：数据库都没准备好，服务也没法工作。'}]}},python:{body:'Python 用自带的 sqlite3 模块操作 SQLite，不用安装任何东西。分两个文件：database.py 负责连接、建表、导入种子数据，并提供两个通用的查询函数；db.py 还是题目的数据访问层，函数名和参数都不变，只是里面改成执行 SQL。\n路由层一行都不用改：查不到时照样返回 None，路由层返回 404；数据库出错会抛出异常，被第 4 关写的中间件接住，返回 500。\nsqlite3 的用法：conn.execute(SQL, 参数) 执行一条语句，参数是一个元组，按顺序对应 SQL 里的 ?；也可以传字典，对应 :名字 这样的命名占位符。executemany 用同一条语句处理一组参数，适合批量插入。',practice:{steps:['新建 data 文件夹，把题库保存为 data/questions.json。','新建 app/database.py（代码第一部分），补完 TODO。','把 app/db.py 换成第二部分，补完 TODO。','按最后一部分修改 main.py。','运行 python main.py，第一次会看到“导入了 24 道题”，项目里多出 data/zixishi.db。重启一次，不会再导入。'],expect:'2026-11-06 10:00:00,123 导入了 24 道题'},code:'# app/database.py\nimport json\nimport os\nimport sqlite3\nfrom contextlib import closing\n\nDB_PATH = os.getenv("DB_PATH", "data/zixishi.db")\n\nSCHEMA = """CREATE TABLE IF NOT EXISTS questions (\n    id         INTEGER PRIMARY KEY,\n    category   TEXT    NOT NULL,\n    title      TEXT    NOT NULL,\n    answer     TEXT    NOT NULL,\n    difficulty INTEGER NOT NULL DEFAULT 1\n)"""\n\n\ndef connect():\n    conn = sqlite3.connect(DB_PATH)\n    conn.row_factory = sqlite3.Row\n    return conn\n\n\ndef query_all(sql, params=()):\n    with closing(connect()) as conn:\n        return [dict(row) for row in conn.execute(sql, params)]\n\n\ndef query_one(sql, params=()):\n    with closing(connect()) as conn:\n        row = conn.execute(sql, params).fetchone()\n        return dict(row) if row else None\n\n\ndef init_db(json_path="data/questions.json"):\n    """建表；表里还没有题目时从 JSON 导入，返回导入的数量"""\n    os.makedirs(os.path.dirname(DB_PATH) or ".", exist_ok=True)\n    with closing(connect()) as conn:\n        with conn:\n            conn.execute(SCHEMA)\n            # TODO 1：执行 SELECT COUNT(*) FROM questions，fetchone() 取出数量，大于 0 就返回 0\n            # TODO 2：用 open(json_path, encoding="utf-8") 和 json.load 读出题目列表\n            # TODO 3：用 conn.executemany 执行 INSERT（用 :id、:category 这样的命名占位符），参数就是题目列表\n            pass\n    # TODO 4：返回导入的数量\n\n# app/db.py\nfrom app.database import query_all, query_one\n\nCOLUMNS = "id, category, title, answer, difficulty"\n\n\ndef list_questions(category=""):\n    """返回某个科目的题目；category 为空时返回全部"""\n    # TODO 5：用 query_all 执行 SELECT {COLUMNS} FROM questions WHERE ? = \'\' OR category = ? ORDER BY id\n    return []\n\n\ndef get_question(qid):\n    """按编号（整数）查找题目，找不到返回 None"""\n    # TODO 6：用 query_one 执行 SELECT {COLUMNS} FROM questions WHERE id = ?\n    return None\n\n# main.py：开头导入 from app.database import init_db，\n# 再把 if __name__ == "__main__": 下面改成先导入数据、再启动\nif __name__ == "__main__":\n    imported = init_db()\n    if imported:\n        log.info("导入了 %d 道题", imported)\n    port = int(os.getenv("PORT", "8080"))\n    uvicorn.run(app, host="127.0.0.1", port=port)',explain:[{at:'# app/database.py',to:'from contextlib import closing',text:'sqlite3 是 Python 自带的模块，不用安装。closing 用来保证连接用完一定会关闭。'},{at:'DB_PATH = os.getenv("DB_PATH", "data/zixishi.db")',text:'数据库文件的位置从环境变量读取，默认 data/zixishi.db。'},{at:'SCHEMA = """CREATE TABLE IF NOT EXISTS questions (',to:')"""',text:'建表语句，三引号可以写多行字符串。id 是主键；NOT NULL 表示不能为空；DEFAULT 1 是不写时的默认值。'},{at:'def connect():',to:'return conn',text:'打开一个连接（文件不存在就创建）。row_factory 设成 sqlite3.Row 后，查出来的每一行可以像字典一样按列名取值。'},{at:'def query_all(sql, params=()):',to:'return [dict(row) for row in conn.execute(sql, params)]',text:'执行查询并返回所有行。with closing(...) 保证不管成功还是出错，离开时都会关闭连接。每一行转成普通字典，FastAPI 就能直接把它变成 JSON。'},{at:'def query_one(sql, params=()):',to:'return dict(row) if row else None',text:'只要第一行：fetchone 没有数据时返回 None。'},{at:'def init_db(json_path="data/questions.json"):',to:'os.makedirs(os.path.dirname(DB_PATH) or ".", exist_ok=True)',text:'先确保数据库所在的文件夹存在。exist_ok=True 表示已经存在也不报错。'},{at:'with closing(connect()) as conn:',to:'conn.execute(SCHEMA)',text:'外层 with 保证连接最后被关闭；内层 with conn 是一个事务：里面的语句全部成功就提交，出现异常就回滚。先建表。'},{at:'pass',text:'补完 TODO 后删掉 pass。'},{at:'# app/db.py',to:'from app.database import query_all, query_one',text:'题目的数据访问层，改成调用 database.py 里的查询函数。'},{at:'COLUMNS = "id, category, title, answer, difficulty"',text:'要查询的列。不用 SELECT *，明确写出需要哪几列。'},{at:'def list_questions(category=""):',to:'return []',text:'按科目查题目，要你补全。'},{at:'def get_question(qid):',to:'return None',text:'按编号查一道题，要你补全。'},{at:'if __name__ == "__main__":',to:'log.info("导入了 %d 道题", imported)',text:'启动服务前先建表、导入种子数据。出错时会抛出异常，程序直接退出并打印原因。'},{at:'port = int(os.getenv("PORT", "8080"))',to:'uvicorn.run(app, host="127.0.0.1", port=port)',text:'然后照常启动服务。'}],solution:{code:'# app/database.py\nimport json\nimport os\nimport sqlite3\nfrom contextlib import closing\n\nDB_PATH = os.getenv("DB_PATH", "data/zixishi.db")\n\nSCHEMA = """CREATE TABLE IF NOT EXISTS questions (\n    id         INTEGER PRIMARY KEY,\n    category   TEXT    NOT NULL,\n    title      TEXT    NOT NULL,\n    answer     TEXT    NOT NULL,\n    difficulty INTEGER NOT NULL DEFAULT 1\n)"""\n\n\ndef connect():\n    conn = sqlite3.connect(DB_PATH)\n    conn.row_factory = sqlite3.Row\n    return conn\n\n\ndef query_all(sql, params=()):\n    with closing(connect()) as conn:\n        return [dict(row) for row in conn.execute(sql, params)]\n\n\ndef query_one(sql, params=()):\n    with closing(connect()) as conn:\n        row = conn.execute(sql, params).fetchone()\n        return dict(row) if row else None\n\n\ndef init_db(json_path="data/questions.json"):\n    """建表；表里还没有题目时从 JSON 导入，返回导入的数量"""\n    os.makedirs(os.path.dirname(DB_PATH) or ".", exist_ok=True)\n    with closing(connect()) as conn:\n        with conn:\n            conn.execute(SCHEMA)\n            (n,) = conn.execute("SELECT COUNT(*) FROM questions").fetchone()\n            if n > 0:\n                return 0\n            with open(json_path, encoding="utf-8") as f:\n                items = json.load(f)\n            conn.executemany(\n                "INSERT INTO questions (id, category, title, answer, difficulty) "\n                "VALUES (:id, :category, :title, :answer, :difficulty)",\n                items,\n            )\n    return len(items)\n\n# app/db.py\nfrom app.database import query_all, query_one\n\nCOLUMNS = "id, category, title, answer, difficulty"\n\n\ndef list_questions(category=""):\n    """返回某个科目的题目；category 为空时返回全部"""\n    return query_all(\n        f"SELECT {COLUMNS} FROM questions WHERE ? = \'\' OR category = ? ORDER BY id",\n        (category, category),\n    )\n\n\ndef get_question(qid):\n    """按编号（整数）查找题目，找不到返回 None"""\n    return query_one(f"SELECT {COLUMNS} FROM questions WHERE id = ?", (qid,))\n\n# main.py：开头导入 from app.database import init_db，\n# 再把 if __name__ == "__main__": 下面改成先导入数据、再启动\nif __name__ == "__main__":\n    imported = init_db()\n    if imported:\n        log.info("导入了 %d 道题", imported)\n    port = int(os.getenv("PORT", "8080"))\n    uvicorn.run(app, host="127.0.0.1", port=port)',explain:[{at:'# app/database.py',to:'from contextlib import closing',text:'sqlite3 是 Python 自带的模块，不用安装。closing 用来保证连接用完一定会关闭。'},{at:'DB_PATH = os.getenv("DB_PATH", "data/zixishi.db")',text:'数据库文件的位置从环境变量读取，默认 data/zixishi.db。'},{at:'SCHEMA = """CREATE TABLE IF NOT EXISTS questions (',to:')"""',text:'建表语句，三引号可以写多行字符串。id 是主键；NOT NULL 表示不能为空；DEFAULT 1 是不写时的默认值。'},{at:'def connect():',to:'return conn',text:'打开一个连接（文件不存在就创建）。row_factory 设成 sqlite3.Row 后，查出来的每一行可以像字典一样按列名取值。'},{at:'def query_all(sql, params=()):',to:'return [dict(row) for row in conn.execute(sql, params)]',text:'执行查询并返回所有行。with closing(...) 保证不管成功还是出错，离开时都会关闭连接。每一行转成普通字典，FastAPI 就能直接把它变成 JSON。'},{at:'def query_one(sql, params=()):',to:'return dict(row) if row else None',text:'只要第一行：fetchone 没有数据时返回 None。'},{at:'def init_db(json_path="data/questions.json"):',to:'os.makedirs(os.path.dirname(DB_PATH) or ".", exist_ok=True)',text:'先确保数据库所在的文件夹存在。'},{at:'with closing(connect()) as conn:',to:'conn.execute(SCHEMA)',text:'外层保证关闭连接，内层 with conn 是一个事务：全部成功就提交，出现异常就回滚。先建表。'},{at:'(n,) = conn.execute("SELECT COUNT(*) FROM questions").fetchone()',to:'return 0',text:'fetchone 返回只有一个元素的行，(n,) = … 把这个元素取出来。已经有题目就跳过。'},{at:'with open(json_path, encoding="utf-8") as f:',to:'items = json.load(f)',text:'读出题目列表，每道题是一个字典。'},{at:'conn.executemany(',to:'items,',text:'对列表里的每个字典执行一次插入，:id 这样的命名占位符会从字典的同名键取值。两段字符串挨着写会自动拼成一段。'},{at:'return len(items)',text:'走到这里说明事务已经提交，返回导入数量。'},{at:'# app/db.py',to:'from app.database import query_all, query_one',text:'题目的数据访问层，改成调用 database.py 里的查询函数。'},{at:'COLUMNS = "id, category, title, answer, difficulty"',text:'要查询的列。不用 SELECT *，明确写出需要哪几列。'},{at:'def list_questions(category=""):',to:'(category, category),',text:'参数为空时 ? = \'\' 成立，返回全部；否则按科目筛选。f 字符串只用来放我们自己写的列名常量，用户传来的 category 一定要通过 ? 传入。'},{at:'def get_question(qid):',to:'return query_one(f"SELECT {COLUMNS} FROM questions WHERE id = ?", (qid,))',text:'按主键查一行。注意 (qid,) 里的逗号：只有一个元素的元组必须这样写。'},{at:'if __name__ == "__main__":',to:'log.info("导入了 %d 道题", imported)',text:'启动服务前先建表、导入种子数据。出错时会抛出异常，程序直接退出并打印原因。'},{at:'port = int(os.getenv("PORT", "8080"))',to:'uvicorn.run(app, host="127.0.0.1", port=port)',text:'然后照常启动服务。'}]}}}},
  {title:'任务三：启动并确认导入',body:'启动服务，看看数据库有没有准备好：\n一、第一次启动，日志里会出现“导入了 24 道题”，项目根目录下多出 data/zixishi.db；\n二、停掉服务再启动，这次不会再导入，因为表里已经有数据了；\n三、打开 http://localhost:8080/api/questions?category=redis ，能看到 5 道 Redis 的题。\n如果启动时报“找不到文件”，检查是不是在项目根目录启动的：data/questions.json 和 data/zixishi.db 都是相对启动目录的路径。',practice:{steps:['在项目根目录启动服务，看日志。','重启一次，确认没有重复导入。','用浏览器打开 /api/questions?category=redis。'],expect:'第一次启动打印“导入了 24 道题”，之后不再打印'},variants:{go:{body:'数据访问层的函数签名变了：List 和 Get 现在都可能返回错误。处理请求的层要分清两种情况：“没找到”返回 404，数据库出错返回 500。\n入口 main.go 负责打开数据库、导入种子数据，出错就直接退出：连数据库都打不开，启动起来也没有意义。',practice:{steps:['按代码修改 handler.go：import 里加上 "errors"，新增 serverError，改写 listQuestions 和 getQuestion。','按代码最后一段修改 main.go。','运行 go run .，第一次会看到“导入了 24 道题”，项目里多出 data/zixishi.db。停掉再启动一次，这次不会再导入。'],expect:'2026/11/06 10:00:00 导入了 24 道题\n2026/11/06 10:00:00 服务已启动：http://localhost:8080'},code:'// internal/handler/handler.go（只列出要改的函数，import 里加上 "errors"）\nfunc (h *Handler) listQuestions(w http.ResponseWriter, r *http.Request) {\n    questions, err := h.store.List(r.URL.Query().Get("category"))\n    if err != nil {\n        h.serverError(w, err)\n        return\n    }\n    writeJSON(w, http.StatusOK, questions)\n}\n\n// serverError 记录错误详情，给用户只返回笼统的 500。\nfunc (h *Handler) serverError(w http.ResponseWriter, err error) {\n    log.Printf("服务器出错：%v", err)\n    writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "服务器内部错误"})\n}\n\nfunc (h *Handler) getQuestion(w http.ResponseWriter, r *http.Request) {\n    id, err := strconv.Atoi(r.PathValue("id"))\n    if err != nil {\n        writeJSON(w, http.StatusBadRequest, map[string]string{"error": "题目编号必须是数字"})\n        return\n    }\n    // TODO：调用 h.store.Get(id)。错误是 store.ErrNotFound 时返回 404 和 {"error": "题目不存在"}；\n    //       其他错误交给 h.serverError；成功时返回题目\n}\n\n// main.go：把原来创建仓库的 store.NewQuestionStore() 换成下面这段，再把 qs 传给 handler.New\ndbPath := os.Getenv("DB_PATH")\nif dbPath == "" {\n    dbPath = "data/zixishi.db"\n}\nqs, err := store.Open(dbPath)\nif err != nil {\n    log.Fatalf("打开数据库失败：%v", err)\n}\nn, err := qs.ImportIfEmpty("data/questions.json")\nif err != nil {\n    log.Fatalf("导入题目失败：%v", err)\n}\nif n > 0 {\n    log.Printf("导入了 %d 道题", n)\n}',explain:[{at:'// internal/handler/handler.go',text:'只改用到仓库的几个函数，其余不变。'},{at:'func (h *Handler) listQuestions(',to:'writeJSON(w, http.StatusOK, questions)',text:'List 现在会返回错误：出错时交给 serverError 统一处理，成功时和以前一样返回列表。'},{at:'func (h *Handler) serverError(',to:'writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "服务器内部错误"})',text:'第 4 关讲过的原则：完整的错误写进日志，用户只看到统一格式的 500。以后每个接口都会用到它。'},{at:'func (h *Handler) getQuestion(',to:'return',text:'编号不是数字返回 400，和以前一样。'},{at:'// TODO：调用 h.store.Get(id)',text:'要你补全：区分“没找到”和“出错了”。'},{at:'// main.go',text:'入口只改“创建仓库”这一处。'},{at:'dbPath := os.Getenv("DB_PATH")',to:'dbPath = "data/zixishi.db"',text:'数据库文件的位置从环境变量读取，默认 data/zixishi.db。'},{at:'qs, err := store.Open(dbPath)',to:'log.Fatalf("打开数据库失败：%v", err)',text:'打开数据库。连数据库都打不开，服务也没法工作，直接打印原因并退出。'},{at:'n, err := qs.ImportIfEmpty("data/questions.json")',to:'log.Fatalf("导入题目失败：%v", err)',text:'导入种子数据，失败同样退出。'},{at:'if n > 0 {',to:'log.Printf("导入了 %d 道题", n)',text:'第一次启动时会打印导入了 24 道题，以后启动表里已有数据，就不再打印。'}],solution:{code:'// internal/handler/handler.go（只列出要改的函数，import 里加上 "errors"）\nfunc (h *Handler) listQuestions(w http.ResponseWriter, r *http.Request) {\n    questions, err := h.store.List(r.URL.Query().Get("category"))\n    if err != nil {\n        h.serverError(w, err)\n        return\n    }\n    writeJSON(w, http.StatusOK, questions)\n}\n\n// serverError 记录错误详情，给用户只返回笼统的 500。\nfunc (h *Handler) serverError(w http.ResponseWriter, err error) {\n    log.Printf("服务器出错：%v", err)\n    writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "服务器内部错误"})\n}\n\nfunc (h *Handler) getQuestion(w http.ResponseWriter, r *http.Request) {\n    id, err := strconv.Atoi(r.PathValue("id"))\n    if err != nil {\n        writeJSON(w, http.StatusBadRequest, map[string]string{"error": "题目编号必须是数字"})\n        return\n    }\n    q, err := h.store.Get(id)\n    if errors.Is(err, store.ErrNotFound) {\n        writeJSON(w, http.StatusNotFound, map[string]string{"error": "题目不存在"})\n        return\n    }\n    if err != nil {\n        h.serverError(w, err)\n        return\n    }\n    writeJSON(w, http.StatusOK, q)\n}\n\n// main.go：把原来创建仓库的 store.NewQuestionStore() 换成下面这段，再把 qs 传给 handler.New\ndbPath := os.Getenv("DB_PATH")\nif dbPath == "" {\n    dbPath = "data/zixishi.db"\n}\nqs, err := store.Open(dbPath)\nif err != nil {\n    log.Fatalf("打开数据库失败：%v", err)\n}\nn, err := qs.ImportIfEmpty("data/questions.json")\nif err != nil {\n    log.Fatalf("导入题目失败：%v", err)\n}\nif n > 0 {\n    log.Printf("导入了 %d 道题", n)\n}',explain:[{at:'// internal/handler/handler.go',text:'只改用到仓库的几个函数，其余不变。'},{at:'func (h *Handler) listQuestions(',to:'writeJSON(w, http.StatusOK, questions)',text:'List 现在会返回错误：出错时交给 serverError 统一处理，成功时和以前一样返回列表。'},{at:'func (h *Handler) serverError(',to:'writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "服务器内部错误"})',text:'第 4 关讲过的原则：完整的错误写进日志，用户只看到统一格式的 500。以后每个接口都会用到它。'},{at:'func (h *Handler) getQuestion(',to:'return',text:'编号不是数字返回 400，和以前一样。'},{at:'q, err := h.store.Get(id)',text:'Get 现在返回 (题目, 错误)。'},{at:'if errors.Is(err, store.ErrNotFound) {',to:'return',text:'没找到是“正常的业务情况”，返回 404。errors.Is 判断错误是不是某个特定的错误值。'},{at:'if err != nil {',to:'return',text:'其他错误是真出问题了，返回 500。'},{at:'writeJSON(w, http.StatusOK, q)',text:'找到了，返回题目。'},{at:'// main.go',text:'入口只改“创建仓库”这一处。'},{at:'dbPath := os.Getenv("DB_PATH")',to:'dbPath = "data/zixishi.db"',text:'数据库文件的位置从环境变量读取，默认 data/zixishi.db。'},{at:'qs, err := store.Open(dbPath)',to:'log.Fatalf("打开数据库失败：%v", err)',text:'打开数据库。连数据库都打不开，服务也没法工作，直接打印原因并退出。'},{at:'n, err := qs.ImportIfEmpty("data/questions.json")',to:'log.Fatalf("导入题目失败：%v", err)',text:'导入种子数据，失败同样退出。'},{at:'if n > 0 {',to:'log.Printf("导入了 %d 道题", n)',text:'第一次启动时会打印导入了 24 道题，以后启动表里已有数据，就不再打印。'}]}},'template-go':{body:'数据访问层的函数签名变了：List 和 Get 现在都可能返回错误。处理请求的层要分清两种情况：“没找到”返回 404，数据库出错返回 500。模板渲染的首页 home 也调用了 List，要一起改。\n入口 main.go 负责打开数据库、导入种子数据，出错就直接退出：连数据库都打不开，启动起来也没有意义。',practice:{steps:['按代码修改 handler.go：import 里加上 "errors"，新增 serverError，改写 listQuestions、getQuestion 和 home。','按代码最后一段修改 main.go。','运行 go run .，第一次会看到“导入了 24 道题”，项目里多出 data/zixishi.db。停掉再启动一次，这次不会再导入。'],expect:'2026/11/06 10:00:00 导入了 24 道题\n2026/11/06 10:00:00 服务已启动：http://localhost:8080'},code:'// internal/handler/handler.go（只列出要改的函数，import 里加上 "errors"）\nfunc (h *Handler) listQuestions(w http.ResponseWriter, r *http.Request) {\n    questions, err := h.store.List(r.URL.Query().Get("category"))\n    if err != nil {\n        h.serverError(w, err)\n        return\n    }\n    writeJSON(w, http.StatusOK, questions)\n}\n\n// serverError 记录错误详情，给用户只返回笼统的 500。\nfunc (h *Handler) serverError(w http.ResponseWriter, err error) {\n    log.Printf("服务器出错：%v", err)\n    writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "服务器内部错误"})\n}\n\nfunc (h *Handler) getQuestion(w http.ResponseWriter, r *http.Request) {\n    id, err := strconv.Atoi(r.PathValue("id"))\n    if err != nil {\n        writeJSON(w, http.StatusBadRequest, map[string]string{"error": "题目编号必须是数字"})\n        return\n    }\n    // TODO：调用 h.store.Get(id)。错误是 store.ErrNotFound 时返回 404 和 {"error": "题目不存在"}；\n    //       其他错误交给 h.serverError；成功时返回题目\n}\n\n// 选模板渲染的同学：home 里也要处理 List 返回的错误\nfunc (h *Handler) home(w http.ResponseWriter, r *http.Request) {\n    category := r.URL.Query().Get("category")\n    questions, err := h.store.List(category)\n    if err != nil {\n        h.serverError(w, err)\n        return\n    }\n    data := map[string]any{\n        "Category":   category,\n        "Categories": []string{"go", "mysql", "redis"},\n        "Questions":  questions,\n    }\n    w.Header().Set("Content-Type", "text/html; charset=utf-8")\n    if err := h.tmpl.ExecuteTemplate(w, "index.html", data); err != nil {\n        log.Printf("渲染页面出错：%v", err)\n    }\n}\n\n// main.go：把原来创建仓库的 store.NewQuestionStore() 换成下面这段，再把 qs 传给 handler.New\ndbPath := os.Getenv("DB_PATH")\nif dbPath == "" {\n    dbPath = "data/zixishi.db"\n}\nqs, err := store.Open(dbPath)\nif err != nil {\n    log.Fatalf("打开数据库失败：%v", err)\n}\nn, err := qs.ImportIfEmpty("data/questions.json")\nif err != nil {\n    log.Fatalf("导入题目失败：%v", err)\n}\nif n > 0 {\n    log.Printf("导入了 %d 道题", n)\n}',explain:[{at:'// internal/handler/handler.go',text:'只改用到仓库的几个函数，其余不变。'},{at:'func (h *Handler) listQuestions(',to:'writeJSON(w, http.StatusOK, questions)',text:'List 现在会返回错误：出错时交给 serverError 统一处理，成功时和以前一样返回列表。'},{at:'func (h *Handler) serverError(',to:'writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "服务器内部错误"})',text:'第 4 关讲过的原则：完整的错误写进日志，用户只看到统一格式的 500。以后每个接口都会用到它。'},{at:'func (h *Handler) getQuestion(',to:'return',text:'编号不是数字返回 400，和以前一样。'},{at:'// TODO：调用 h.store.Get(id)',text:'要你补全：区分“没找到”和“出错了”。'},{at:'func (h *Handler) home(',to:'log.Printf("渲染页面出错：%v", err)',text:'首页同样先处理 List 的错误再渲染。科目列表加上了新的 redis。'},{at:'// main.go',text:'入口只改“创建仓库”这一处。'},{at:'dbPath := os.Getenv("DB_PATH")',to:'dbPath = "data/zixishi.db"',text:'数据库文件的位置从环境变量读取，默认 data/zixishi.db。'},{at:'qs, err := store.Open(dbPath)',to:'log.Fatalf("打开数据库失败：%v", err)',text:'打开数据库。连数据库都打不开，服务也没法工作，直接打印原因并退出。'},{at:'n, err := qs.ImportIfEmpty("data/questions.json")',to:'log.Fatalf("导入题目失败：%v", err)',text:'导入种子数据，失败同样退出。'},{at:'if n > 0 {',to:'log.Printf("导入了 %d 道题", n)',text:'第一次启动时会打印导入了 24 道题，以后启动表里已有数据，就不再打印。'}],solution:{code:'// internal/handler/handler.go（只列出要改的函数，import 里加上 "errors"）\nfunc (h *Handler) listQuestions(w http.ResponseWriter, r *http.Request) {\n    questions, err := h.store.List(r.URL.Query().Get("category"))\n    if err != nil {\n        h.serverError(w, err)\n        return\n    }\n    writeJSON(w, http.StatusOK, questions)\n}\n\n// serverError 记录错误详情，给用户只返回笼统的 500。\nfunc (h *Handler) serverError(w http.ResponseWriter, err error) {\n    log.Printf("服务器出错：%v", err)\n    writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "服务器内部错误"})\n}\n\nfunc (h *Handler) getQuestion(w http.ResponseWriter, r *http.Request) {\n    id, err := strconv.Atoi(r.PathValue("id"))\n    if err != nil {\n        writeJSON(w, http.StatusBadRequest, map[string]string{"error": "题目编号必须是数字"})\n        return\n    }\n    q, err := h.store.Get(id)\n    if errors.Is(err, store.ErrNotFound) {\n        writeJSON(w, http.StatusNotFound, map[string]string{"error": "题目不存在"})\n        return\n    }\n    if err != nil {\n        h.serverError(w, err)\n        return\n    }\n    writeJSON(w, http.StatusOK, q)\n}\n\n// 选模板渲染的同学：home 里也要处理 List 返回的错误\nfunc (h *Handler) home(w http.ResponseWriter, r *http.Request) {\n    category := r.URL.Query().Get("category")\n    questions, err := h.store.List(category)\n    if err != nil {\n        h.serverError(w, err)\n        return\n    }\n    data := map[string]any{\n        "Category":   category,\n        "Categories": []string{"go", "mysql", "redis"},\n        "Questions":  questions,\n    }\n    w.Header().Set("Content-Type", "text/html; charset=utf-8")\n    if err := h.tmpl.ExecuteTemplate(w, "index.html", data); err != nil {\n        log.Printf("渲染页面出错：%v", err)\n    }\n}\n\n// main.go：把原来创建仓库的 store.NewQuestionStore() 换成下面这段，再把 qs 传给 handler.New\ndbPath := os.Getenv("DB_PATH")\nif dbPath == "" {\n    dbPath = "data/zixishi.db"\n}\nqs, err := store.Open(dbPath)\nif err != nil {\n    log.Fatalf("打开数据库失败：%v", err)\n}\nn, err := qs.ImportIfEmpty("data/questions.json")\nif err != nil {\n    log.Fatalf("导入题目失败：%v", err)\n}\nif n > 0 {\n    log.Printf("导入了 %d 道题", n)\n}',explain:[{at:'// internal/handler/handler.go',text:'只改用到仓库的几个函数，其余不变。'},{at:'func (h *Handler) listQuestions(',to:'writeJSON(w, http.StatusOK, questions)',text:'List 现在会返回错误：出错时交给 serverError 统一处理，成功时和以前一样返回列表。'},{at:'func (h *Handler) serverError(',to:'writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "服务器内部错误"})',text:'第 4 关讲过的原则：完整的错误写进日志，用户只看到统一格式的 500。以后每个接口都会用到它。'},{at:'func (h *Handler) getQuestion(',to:'return',text:'编号不是数字返回 400，和以前一样。'},{at:'q, err := h.store.Get(id)',text:'Get 现在返回 (题目, 错误)。'},{at:'if errors.Is(err, store.ErrNotFound) {',to:'return',text:'没找到是“正常的业务情况”，返回 404。errors.Is 判断错误是不是某个特定的错误值。'},{at:'if err != nil {',to:'return',text:'其他错误是真出问题了，返回 500。'},{at:'writeJSON(w, http.StatusOK, q)',text:'找到了，返回题目。'},{at:'func (h *Handler) home(',to:'log.Printf("渲染页面出错：%v", err)',text:'首页同样先处理 List 的错误再渲染。科目列表加上了新的 redis。'},{at:'// main.go',text:'入口只改“创建仓库”这一处。'},{at:'dbPath := os.Getenv("DB_PATH")',to:'dbPath = "data/zixishi.db"',text:'数据库文件的位置从环境变量读取，默认 data/zixishi.db。'},{at:'qs, err := store.Open(dbPath)',to:'log.Fatalf("打开数据库失败：%v", err)',text:'打开数据库。连数据库都打不开，服务也没法工作，直接打印原因并退出。'},{at:'n, err := qs.ImportIfEmpty("data/questions.json")',to:'log.Fatalf("导入题目失败：%v", err)',text:'导入种子数据，失败同样退出。'},{at:'if n > 0 {',to:'log.Printf("导入了 %d 道题", n)',text:'第一次启动时会打印导入了 24 道题，以后启动表里已有数据，就不再打印。'}]}}}},
  {title:'任务四：页面加上新科目',body:'题库多了 redis 科目，页面上的科目按钮也要跟着加上：\n原生 HTML：在 index.html 的 nav 里加一个 <button data-category="redis">redis</button>；\nReact：把 App.jsx 里的 categories 数组改成 ["", "go", "mysql", "redis"]；\n模板渲染：把首页传给模板的科目列表加上 "redis"（Go 的同学在任务三里已经改好了）。\n科目写死在前端或者首页代码里并不理想：以后再加科目，还要改代码。下一关会做一个“科目列表”接口，页面从接口读取科目，就不用再改了。',practice:{steps:['按你的前端做法加上 redis 科目。','打开 http://localhost:8080/ ，点 redis，能看到 5 道题。'],expect:'页面上有 全部、go、mysql、redis 四个科目'}},
  {title:'验收：数据来自数据库',body:'验收脚本检查接口返回的是数据库里的 24 道题，筛选和详情都正确，还会做两项新的检查：\n一、查一个不存在的科目，要返回 200 和空列表 []，而不是 404 或者 null：“列表为空”是正常结果；\n二、模拟一次 SQL 注入：科目参数传 \' OR \'1\'=\'1。用了参数化查询的接口会把它当作一个普通的（不存在的）科目名，返回空列表；如果返回了 24 道题，说明你拼接了 SQL，必须改。\n另外自己确认一下：重启服务后不会重复导入；删掉 data/zixishi.db 再启动，会重新建表、重新导入。',practice:{steps:['保持服务在运行。','把下面的脚本保存为 checks/check_l6.py，运行 python checks/check_l6.py，直到全部 ✓。','全部通过后提交：git add . 然后 git commit -m "第 6 关：题库数据库"。提交前用 git status 确认 data/zixishi.db 没有出现在要提交的文件里。'],expect:'✓ 健康检查仍然正常\n✓ 题目列表返回 24 道题\n✓ 每道题都有 5 个字段\n✓ 按科目筛选：go 11 道、redis 5 道\n✓ 题目详情返回第 24 题\n✓ 不存在的题目返回 404\n✓ 编号不是数字返回 400\n✓ 不存在的科目返回空列表\n✓ SQL 注入试探返回空列表\n\n通过 9 / 9'},code:`import json
import sys
import urllib.error
import urllib.parse
import urllib.request

BASE = sys.argv[1] if len(sys.argv) > 1 else "http://localhost:8080"
passed = 0


def check(name, ok):
    global passed
    print(("✓ " if ok else "✗ ") + name)
    passed += bool(ok)


def get(path):
    try:
        with urllib.request.urlopen(BASE + path, timeout=5) as r:
            status, body = r.status, r.read()
    except urllib.error.HTTPError as e:
        status, body = e.code, e.read()
    except OSError as e:
        sys.exit(f"连不上 {BASE}，服务启动了吗？（{e}）")
    try:
        return status, json.loads(body.decode("utf-8") or "null")
    except ValueError:
        return status, None


def count(category):
    _, data = get("/api/questions?category=" + urllib.parse.quote(category))
    return len(data) if isinstance(data, list) else -1


status, data = get("/api/health")
check("健康检查仍然正常", status == 200 and data == {"status": "ok"})

status, data = get("/api/questions")
check("题目列表返回 24 道题", status == 200 and isinstance(data, list) and len(data) == 24)
fields = {"id", "category", "title", "answer", "difficulty"}
check("每道题都有 5 个字段", isinstance(data, list) and all(set(q) == fields for q in data))

check("按科目筛选：go 11 道、redis 5 道", count("go") == 11 and count("redis") == 5)

status, data = get("/api/questions/24")
check("题目详情返回第 24 题", status == 200 and isinstance(data, dict) and "分布式锁" in data.get("title", ""))
status, _ = get("/api/questions/999")
check("不存在的题目返回 404", status == 404)
status, _ = get("/api/questions/abc")
check("编号不是数字返回 400", status == 400)

status, data = get("/api/questions?category=java")
check("不存在的科目返回空列表", status == 200 and data == [])
status, data = get("/api/questions?category=" + urllib.parse.quote("' OR '1'='1"))
check("SQL 注入试探返回空列表", status == 200 and data == [])

print(f"\\n通过 {passed} / 9")`,explain:[{at:'import json',to:'import urllib.request',text:'urllib.parse 用来把参数里的特殊字符（空格、引号）编码成地址里安全的写法。'},{at:'BASE = sys.argv[1]',to:'passed = 0',text:'服务地址和通过数。'},{at:'def check(name, ok):',to:'passed += bool(ok)',text:'检查一项并打印结果。'},{at:'def get(path):',to:'return status, None',text:'发 GET 请求，返回状态码和解析好的 JSON（不是 JSON 时为 None），和第 3 关一样。'},{at:'def count(category):',to:'return len(data) if isinstance(data, list) else -1',text:'查某个科目有几道题；返回的不是列表就记为 -1，肯定对不上。'},{at:'status, data = get("/api/health")',to:'check("健康检查仍然正常"',text:'健康检查。'},{at:'status, data = get("/api/questions")',to:'check("每道题都有 5 个字段"',text:'列表要有 24 道题；set(q) 取出每道题的所有键，要正好是这 5 个字段，多了少了都不行。'},{at:'check("按科目筛选：go 11 道、redis 5 道"',text:'按科目筛选，数量要和 questions.json 一致。'},{at:'status, data = get("/api/questions/24")',to:'check("编号不是数字返回 400", status == 400)',text:'详情、404、400，和以前的约定一样。第 24 题是新导入的，能查到说明数据确实来自数据库。'},{at:'status, data = get("/api/questions?category=java")',to:'check("不存在的科目返回空列表"',text:'没有 java 科目的题，应该返回 200 和 []。'},{at:'status, data = get("/api/questions?category=" + urllib.parse.quote',to:'check("SQL 注入试探返回空列表"',text:'模拟 SQL 注入。参数化查询会把整串字符当作科目名，查不到任何题。'},{at:'print(f"\\n通过 {passed} / 9")',text:'打印总的通过数。'}]},
  {title:'以后换成 MySQL 要改什么',body:'SQLite 适合学习和小网站，用户多了、需要多台服务器共用一个数据库时，一般换成 MySQL 或 PostgreSQL。因为我们分了层、用了标准 SQL，要改的地方很集中：\n一、驱动和连接地址：Go 换成 github.com/go-sql-driver/mysql，Java 换成 mysql-connector-j，Node.js 换成 mysql2，Python 换成 PyMySQL，地址里写上主机、端口、用户名、密码（密码从环境变量读取）；\n二、少量 SQL 语法差异：比如 MySQL 的自增主键写 AUTO_INCREMENT，文本类型常用 VARCHAR(长度)；\n三、Node.js 和 Python 的 MySQL 库多是异步的，查询要加 await。\n处理请求的层、前端页面都不用动。这就是第 4 关分层带来的好处。'},
  {title:'这一关学到了什么',body:'一、数据库由表组成，表有列（字段和类型）和行（一条条数据），主键唯一确定一行；\n二、四种基本 SQL：CREATE TABLE 建表、INSERT 插入、SELECT 查询、COUNT 计数；\n三、用户传来的值一律通过占位符传入，绝不拼接 SQL，防止 SQL 注入；\n四、一组必须一起成功的写操作放进事务，要么全做，要么全不做；\n五、种子数据提交到 Git，数据库文件不提交；数据库位置从环境变量读取；\n六、数据访问层只返回数据或“没找到”，出错时把错误交给上层，最终变成 500 和一行日志。'}
 ],quiz:[
 {id:'pj-db-1',q:'把题目从代码里搬进数据库，最主要的好处是？',options:['加题不改代码，重启数据也不丢','接口返回的速度会快上好多倍','前端可以直接连接数据库读数据','不再需要后端，页面直接读文件'],why:['','内存读取本来就很快，换数据库主要不是为了速度。','前端直接连数据库会暴露密码，数据要经过后端接口。','业务规则、权限检查仍然要由后端完成。'],answer:0,explain:'代码里的数据只能随代码一起修改，程序重启也会丢失运行中的变化。数据库把数据长期保存下来，后面的用户、学习记录也都要存进去。'},
 {id:'pj-db-2',type:'judge',q:'CREATE TABLE IF NOT EXISTS 在表已经存在时会报错，所以只能在第一次启动时执行。',answer:false,explain:'错误。IF NOT EXISTS 的意思正是“表已经存在就什么也不做”，所以每次启动都可以放心执行。'},
 {id:'pj-db-3',q:'下面哪种写法能防止 SQL 注入？',options:['用 ? 占位符，参数和 SQL 分开传','把参数里的单引号全部删掉再拼','整条 SQL 转成大写之后再执行','用加号把参数拼进 SQL 字符串'],why:['','删字符的过滤很容易被绕过，也会误伤正常数据。','大小写和注入无关。','拼接正是 SQL 注入的根源。'],answer:0,explain:'参数化查询让数据库只把参数当作一个值，绝不会当作 SQL 的一部分执行。用户传来的任何值都应该通过占位符传入。'},
 {id:'pj-db-4',q:'导入 24 道题时为什么要放在一个事务里？',options:['中途出错时全部回滚，不会只导入一半','事务可以让每道题自动生成编号','不用事务的话数据库不允许插入','事务会把数据同时备份到另一个文件'],why:['','编号来自 JSON 里的 id，和事务无关。','不用事务也能插入，只是每条单独提交。','事务不负责备份。'],answer:0,explain:'事务保证一组操作要么全做、要么全不做。如果只导入了一半，下次启动时“表里已有数据”，就再也不会补全了。顺带一提，SQLite 一次提交很多条插入也快得多。'},
 {id:'pj-db-5',type:'multi',q:'关于主键（PRIMARY KEY），下面说法正确的有？（多选）',options:['同一张表里主键的值不能重复','能唯一确定表里的一行数据','数据库会自动给它建索引','主键也可以由几列合起来组成'],why:['','','',''],answers:[0,1,2,3],explain:'主键唯一标识一行，不能重复，按主键查询有索引支持。主键也可以由几列组成（联合主键），第 10 关的学习记录表就会用到。类型不限，常用整数自增或字符串编号。'},
 {id:'pj-db-6',q:'查询一个不存在的科目时，题目列表接口最合适的返回是？',options:['200 和空列表 []','404 和一条错误信息','500 服务器内部错误','200 和 null'],why:['','列表接口查不到数据是正常结果，不是“资源不存在”。','没有出错，不应该返回 500。','null 会让前端遍历时报错，空列表更好处理。'],answer:0,explain:'“列表为空”是正常结果，返回 200 和 []，前端照常显示“共 0 道题”。404 留给“按编号查找的那一个东西不存在”这种情况。'},
 {id:'pj-db-7',type:'fill',q:'一组数据库操作要么全部成功生效，要么全部撤销，这组操作叫做 ＿。',accepted:['事务','transaction'],explain:'事务（transaction）。成功时提交（commit），出错时回滚（rollback）。'},
 {id:'pj-db-8',type:'judge',q:'数据库文件 data/zixishi.db 应该和种子数据 data/questions.json 一起提交到 Git。',answer:false,explain:'错误。种子数据是题库的源头，要提交；数据库文件是运行时生成的，以后还会有用户密码和学习记录，不应该提交，用 .gitignore 忽略。'},
 {id:'pj-db-9',type:'short',q:'有人请求 /api/questions?category=\' OR \'1\'=\'1。分别说说：用字符串拼接 SQL 和用参数化查询，会发生什么？',reference:'拼接时 SQL 变成 WHERE category = \'\' OR \'1\'=\'1\'，条件永远成立，返回所有题目，攻击者还可能借此执行别的语句；参数化查询时，整串字符只是一个科目名，查不到任何题，返回空列表。',points:['拼接后条件永远成立，返回全部数据（SQL 注入）','参数化时整串只是一个普通的值','参数化查询返回空列表，不会执行注入的语句'],explain:'这就是验收脚本里“SQL 注入试探”那一项检查的原理。'},
 {id:'pj-db-go-1',stack:'go',q:'导入 SQLite 驱动时写成 _ "modernc.org/sqlite"，下划线的作用是？',options:['只让驱动注册自己，代码里不直接用','把这个包改名为下划线方便调用','让这个包只在测试的时候才导入','表示这个包的版本号可以随意'],why:['','下划线导入后，代码里没法通过名字使用它。','和测试无关。','版本写在 go.mod 里，和导入写法无关。'],answer:0,explain:'导入包时会执行它的 init 函数，驱动在那里把自己注册成 "sqlite"。之后通过 database/sql 的 sql.Open("sqlite", …) 使用，不直接调用驱动包，所以用下划线导入。'},
 {id:'pj-db-go-2',stack:'go',q:'Go 的 QueryRow(...).Scan(...) 查不到数据时返回什么错误？',options:['sql.ErrNoRows','nil','io.EOF','os.ErrNotExist'],why:['','查不到时会返回错误，不是 nil。','io.EOF 表示读到了流的末尾，数据库查询不用它。','这是文件不存在的错误。'],answer:0,explain:'没有结果时 Scan 返回 sql.ErrNoRows。我们在数据访问层把它翻译成自己的 store.ErrNotFound，处理请求的层用 errors.Is 判断后返回 404。'},
 {id:'pj-db-java-1',stack:'java',q:'JdbcTemplate 里的 RowMapper 是做什么用的？',options:['把查询结果的一行转换成一个 Java 对象','把 Java 对象自动保存成新的一行','负责创建和管理数据库连接','把 SQL 语句翻译成另一种数据库的写法'],why:['','保存数据用的是 update 或 batchUpdate。','连接由连接池（HikariCP）管理。','JdbcTemplate 不翻译 SQL。'],answer:0,explain:'RowMapper 是一个函数：给它结果集的当前行，它按列名取出值，创建一个 Question。query 方法对每一行调用它，得到对象列表。'},
 {id:'pj-db-node-1',stack:'node',q:'better-sqlite3 中，stmt.get(id) 在没有查到数据时返回什么？',options:['undefined','空数组 []','抛出一个异常','null'],why:['','.all() 查不到时才返回空数组。','查不到数据不算错误，不会抛异常。','better-sqlite3 用的是 undefined。'],answer:0,explain:'.get() 返回第一行，没有时是 undefined；路由层判断 if (!question) 返回 404。.all() 返回所有行组成的数组，没有时是 []。'},
 {id:'pj-db-python-1',stack:'python',q:'Python sqlite3 里 conn.row_factory = sqlite3.Row 的作用是？',options:['查询结果的每一行可以按列名取值','让查询结果自动按 id 排序','让每次查询都自动开启一个事务','把查询结果直接转换成 JSON 字符串'],why:['','排序要在 SQL 里写 ORDER BY。','事务由 with conn 控制。','转成 JSON 是 FastAPI 做的，我们先用 dict(row) 转成字典。'],answer:0,explain:'默认每一行是一个元组，只能按位置取值。设成 sqlite3.Row 后可以写 row["title"]，也能用 dict(row) 转成字典。'},
]};
